    std::vector<int> minimumWeight(std::vector<std::vector<int>>& edges, std::vector<std::vector<int>>& queries) {
        int n = edges.size() + 1;
        std::vector<std::vector<std::pair<int, int>>> graph(n);
        for (const auto& e : edges) {
            graph[e[0]].push_back({e[1], e[2]});
            graph[e[1]].push_back({e[0], e[2]});
        }

        int LOG = 0;
        while ((1 << LOG) <= n) LOG++;
        LOG++;

        std::vector<std::vector<int>> up(n, std::vector<int>(LOG, 0));
        std::vector<int> depth(n, 0);
        std::vector<long long> dist(n, 0);

        std::queue<int> q;
        std::vector<bool> visited(n, false);
        q.push(0);
        visited[0] = true;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (const auto& [v, w] : graph[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    up[v][0] = u;
                    depth[v] = depth[u] + 1;
                    dist[v] = dist[u] + w;
                    q.push(v);
                }
            }
        }

        for (int j = 1; j < LOG; ++j) {
            for (int i = 0; i < n; ++i) {
                up[i][j] = up[up[i][j - 1]][j - 1];
            }
        }

        auto lca = [&](int u, int v) -> int {
            if (depth[u] > depth[v]) std::swap(u, v);
            int diff = depth[v] - depth[u];
            for (int i = 0; i < LOG; ++i) {
                if ((diff >> i) & 1) {
                    v = up[v][i];
                }
            }
            if (u == v) return u;
            for (int i = LOG - 1; i >= 0; --i) {
                if (up[u][i] != up[v][i]) {
                    u = up[u][i];
                    v = up[v][i];
                }
            }
            return up[u][0];
        };

        auto distance = [&](int u, int v) -> long long {
            return dist[u] + dist[v] - 2 * dist[lca(u, v)];
        };

        std::vector<int> ans;
        ans.reserve(queries.size());
        for (const auto& query : queries) {
            int s1 = query[0], s2 = query[1], d = query[2];
            long long total = distance(s1, s2) + distance(s1, d) + distance(s2, d);
            ans.push_back((int)(total / 2));
        }
        return ans;
    }
