import java.util.*;

class Solution {
    public int[] minimumWeight(int[][] edges, int[][] queries) {
        int n = edges.length + 1;
        List<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; ++i) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(new int[]{e[1], e[2]});
            graph[e[1]].add(new int[]{e[0], e[2]});
        }

        int LOG = 1;
        while ((1 << LOG) <= n) LOG++;
        LOG++;

        int[][] up = new int[n][LOG];
        int[] depth = new int[n];
        long[] dist = new long[n];

        Queue<Integer> q = new LinkedList<>();
        boolean[] visited = new boolean[n];
        q.offer(0);
        visited[0] = true;

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int[] edge : graph[u]) {
                int v = edge[0], w = edge[1];
                if (!visited[v]) {
                    visited[v] = true;
                    up[v][0] = u;
                    depth[v] = depth[u] + 1;
                    dist[v] = dist[u] + w;
                    q.offer(v);
                }
            }
        }

        for (int j = 1; j < LOG; ++j) {
            for (int i = 0; i < n; ++i) {
                up[i][j] = up[up[i][j - 1]][j - 1];
            }
        }

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            int s1 = queries[i][0], s2 = queries[i][1], d = queries[i][2];
            long d12 = getDistance(s1, s2, up, depth, dist, LOG);
            long d1d = getDistance(s1, d, up, depth, dist, LOG);
            long d2d = getDistance(s2, d, up, depth, dist, LOG);
            ans[i] = (int)((d12 + d1d + d2d) / 2);
        }
        return ans;
    }

    private long getDistance(int u, int v, int[][] up, int[] depth, long[] dist, int LOG) {
        return dist[u] + dist[v] - 2 * dist[getLca(u, v, up, depth, LOG)];
    }

    private int getLca(int u, int v, int[][] up, int[] depth, int LOG) {
        if (depth[u] > depth[v]) {
            int t = u; u = v; v = t;
        }
        int diff = depth[v] - depth[u];
        for (int i = 0; i < LOG; ++i) {
            if (((diff >> i) & 1) != 0) {
                v = up[v][i];
            }
        }
        if (u == v) return u;
        for (int i = LOG - 1; i >= 0; --i) {
            if (up[u][i] != up[v][i]) {
                u = up[u][i];
                v = up[v][i];
            }
        }
        return up[u][0];
    }
}

