var minimumWeight = function(edges, queries) {
    const n = edges.length + 1;
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        graph[u].push([v, w]);
        graph[v].push([u, w]);
    }

    let LOG = 1;
    while ((1 << LOG) <= n) LOG++;
    LOG++;

    const up = Array.from({ length: n }, () => new Array(LOG).fill(0));
    const depth = new Array(n).fill(0);
    const dist = new Array(n).fill(0);

    const q = [0];
    const visited = new Array(n).fill(false);
    visited[0] = true;

    while (q.length > 0) {
        const u = q.shift();
        for (const [v, w] of graph[u]) {
            if (!visited[v]) {
                visited[v] = true;
                up[v][0] = u;
                depth[v] = depth[u] + 1;
                dist[v] = dist[u] + w;
                q.push(v);
            }
        }
    }

    for (let j = 1; j < LOG; ++j) {
        for (let i = 0; i < n; ++i) {
            up[i][j] = up[up[i][j - 1]][j - 1];
        }
    }

    function lca(u, v) {
        if (depth[u] > depth[v]) [u, v] = [v, u];
        let diff = depth[v] - depth[u];
        for (let i = 0; i < LOG; ++i) {
            if ((diff >> i) & 1) {
                v = up[v][i];
            }
        }
        if (u === v) return u;
        for (let i = LOG - 1; i >= 0; --i) {
            if (up[u][i] !== up[v][i]) {
                u = up[u][i];
                v = up[v][i];
            }
        }
        return up[u][0];
    }

    function distance(u, v) {
        return dist[u] + dist[v] - 2 * dist[lca(u, v)];
    }

    const ans = [];
    for (const [s1, s2, d] of queries) {
        const total = distance(s1, s2) + distance(s1, d) + distance(s2, d);
        ans.push(Math.floor(total / 2));
    }
    return ans;
};
